/* 半破/滚球 定性辅助数据层（_7m_db 真实赛果，gen_teamctx.cjs 产出；gzip+base64，解压后挂 window.TEAMCTX）*/
window.__TC_GZ__="";
(async function(){try{var s=window.__TC_GZ__;if(!s||window.TEAMCTX)return;var bin=atob(s),n=bin.length,u=new Uint8Array(n);for(var i=0;i<n;i++)u[i]=bin.charCodeAt(i);if(typeof DecompressionStream!=='function')throw new Error('无 DecompressionStream');var buf=await new Response(new Blob([u]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();window.TEAMCTX=JSON.parse(new TextDecoder('utf-8').decode(new Uint8Array(buf)));}catch(e){console.warn('[teamctx] 解压失败:',e);}})();
